import {client} from './api.mjs';
import {makeStudio} from './studio.mjs';
import {makeProduction} from './production.mjs';
import {makeAdvanced} from './advanced.mjs';
import {makeGovernance} from './governance.mjs';
import {makeFiveWaves} from './waves.mjs';
import {getLocale,setLocale,translateUI} from './i18n.mjs';
import {clientUUID,ACTIONS, DEMOS, EVENT_NAMES, analyze, briefText, dialogue,comparison,makeBrief} from '../shared/domain.mjs';

// All author and model content passes through esc; no user HTML is trusted.
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
  logo:'<path d="M4 20 12 4l8 16M7 15h10M12 4v7"/>', home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
  scale:'<path d="M12 3v17M7 21h10M4 7h16M5 7l-3 7h6L5 7Zm14 0-3 7h6l-3-7ZM9 5h6"/>',folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10H3Z"/>', target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>', file:'<path d="M14 2H5v20h14V7ZM14 2v5h5M8 12h8M8 16h6"/>', spark:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',check:'<path d="m5 12 4 4L19 6"/>', alert:'<path d="m12 3 10 18H2Z"/><path d="M12 9v4m0 4h.01"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  link:'<path d="m10 14 4-4m-5 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 8a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-2 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-15a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5"/>',
  copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', x:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',exit:'<path d="M9 3H3v18h6m0-9h12m-5-5 5 5-5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6v15h12V6M10 10v7m4-7v7"/>', refresh:'<path d="M20 11a8 8 0 1 0-2 7M20 4v7h-7"/>'
};
const I = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const B = (text, action, cls='', extras='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${extras}>${text}</button>`;
const date = value => new Date(value).toLocaleString(getLocale()==='zh'?'zh-CN':getLocale()==='en'?'en-US':'ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const phaseName = p => ({hearing:'На рассмотрении',revision:'Уточнение',review:'Выбор формулировки',ready:'Подготовлено',verdict:'Бриф готов',reopened:'Есть возражение'}[p]||p);
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
let boot=null, current=null, selectedRole='lex', selectedVariant='', viewToken=0, busy=false;
let modalReturn=null;
const route=()=>location.hash.slice(1)||'/';
const studio=makeStudio({client,esc,B,I,shell:(...args)=>shell(...args),heading:(...args)=>heading(...args),showModal:(...args)=>showModal(...args),closeModal:()=>closeModal(),toast:(...args)=>toast(...args),copy:(...args)=>copy(...args),download:(...args)=>download(...args),navigate:p=>navigate(p),render:()=>render(),boot:()=>boot,caseDetail:()=>current});
const navigate=path=>{if(route()===path)render();else location.hash=path;};
const production=makeProduction({client,esc,B,I,shell:(...args)=>shell(...args),heading:(...args)=>heading(...args),showModal:(...args)=>showModal(...args),closeModal:()=>closeModal(),toast:(...args)=>toast(...args),download:(...args)=>download(...args),navigate:p=>navigate(p),boot:()=>boot,getLocale:()=>getLocale()});
const advanced=makeAdvanced({client,esc,B,I,shell:(...args)=>shell(...args),heading:(...args)=>heading(...args),showModal:(...args)=>showModal(...args),closeModal:()=>closeModal(),toast:(...args)=>toast(...args),download:(...args)=>download(...args),navigate:p=>navigate(p),boot:()=>boot,getLocale:()=>getLocale()});
const governance=makeGovernance({client,esc,B,I,shell:(...args)=>shell(...args),heading:(...args)=>heading(...args),showModal:(...args)=>showModal(...args),closeModal:()=>closeModal(),toast:(...args)=>toast(...args),download:(...args)=>download(...args),navigate:p=>navigate(p),boot:()=>boot});
const waves=makeFiveWaves({client,esc,B,I,shell:(...args)=>shell(...args),heading:(...args)=>heading(...args),showModal:(...args)=>showModal(...args),closeModal:()=>closeModal(),toast:(...args)=>toast(...args),navigate:p=>navigate(p),boot:()=>boot});
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');translateUI(el);clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),6000);}
function showModal(title,body){modalReturn=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Закрыть">${I('x')}</button></div>${body}`;modal.showModal();translateUI(modal);}
function closeModal(){modal.close();modalReturn?.focus?.();}
modal.addEventListener('click', e=>{if(e.target===modal)closeModal();});
modal.addEventListener('close',()=>modalReturn?.focus?.());
function errorIn(el,e){const block=el?.querySelector('.inline-error');if(block){block.textContent=e.message;block.hidden=false;block.scrollIntoView({block:'nearest'});}else toast(e.message);}
async function copy(value){try {await navigator.clipboard.writeText(value);toast('Скопировано.');}catch{showModal('Скопируйте текст',`<p class="modal-sub">Браузер не разрешил доступ к буферу. Выделите текст и скопируйте его вручную.</p><textarea class="link-box" readonly>${esc(value)}</textarea>`);modal.querySelector('textarea').select();}}
function download(name,value,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function syncBoot(){boot=await client.bootstrap();return boot;}
function footer(){return `<footer class="footer"><span>JUDGE / ADVERSE <span class="mono">v${esc(boot?.version||'0.30.0')}</span> · Локальный пилот</span><span>Не юридическое заключение. Не прогноз продаж. <button data-action="privacy">О данных</button></span></footer>`;}
function shell(content,title='Рабочий кабинет',active='home'){
  const nav=[['home','home','Обзор','/'],['cases','folder','Мои дела','/cases'],['workspaces','users','Команды','/workspaces'],['campaigns','folder','Кампании','/campaigns'],['research','target','Исследования','/research'],['analytics','target','Аналитика','/analytics'],['method','book','Как это работает','/method'],['platforms','link','Семь платформ','/platforms'],['settings','settings','Настройки','/settings']];
  app.innerHTML=`<aside class="sidebar" id="sidebar"><a href="#/" class="brand"><span class="brand-mark">${I('logo')}</span>ADVERSE</a><div class="workspace"><div class="workspace-symbol">J</div><div><strong>JUDGE</strong><small>СТУДИЯ СМЫСЛА</small></div></div><div class="nav-title">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav aria-label="Основная навигация">${nav.map(([key,icon,label,path])=>`<a href="#${path}" class="nav-item ${key===active?'active':''}" ${key===active?'aria-current="page"':''}>${I(icon)}${label}${key===active?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="nav-separator"></div>${boot?.mode==='preview'?'':`<a href="/cinema/" class="nav-item nav-cinema">${I('spark')}Интерактивный фильм <span class="nav-dot"></span></a>`}<a href="#/new" class="nav-item">${I('plus')}Новое дело</a><div class="sidebar-foot"><span class="mode-dot"></span>${boot?.mode==='preview'?'Автономное превью':'Сохранение на сервере'}<p>${boot?.mode==='preview'?'Данные только в этом браузере.':'Ваши решения становятся историей дела, а не исчезают в чате.'}</p></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="close mobile-menu" data-action="menu" aria-label="Меню" aria-expanded="false">${I('menu')}</button><span class="muted">Рабочее пространство</span><span class="divider">/</span><strong>${esc(title)}</strong></div><div class="topbar-right"><select id="judge-locale" class="locale-switch" aria-label="Language"><option value="ru" ${getLocale()==="ru"?"selected":""}>RU</option><option value="en" ${getLocale()==="en"?"selected":""}>EN</option><option value="zh" ${getLocale()==="zh"?"selected":""}>中文</option></select><span class="pill"><span class="mode-dot"></span>${boot?.ai?.enabled?'ИИ настроен · по согласию':'Сценарный режим'}</span><button class="profile-button" data-action="account"><span class="avatar-small">${boot?.user?'M':'Г'}</span><span>${esc(boot?.user?.email||'Гостевой доступ')}</span></button></div></header>${boot?.mode==='preview'?'<div class="preview-banner">АВТОНОМНОЕ ПРЕВЬЮ · Разбор и экспорт работают локально. Аккаунты, свидетели и подключения доступны в серверной сборке.</div>':''}<main id="main" tabindex="-1" class="page">${content}${footer()}</main></div>`;
 translateUI(document.querySelector("#app"));
 if(boot?.mode==='preview'&&boot.storageAvailable===false){document.querySelector('.preview-banner').textContent='АВТОНОМНОЕ ПРЕВЬЮ · Хранилище браузера недоступно: после закрытия страницы дела исчезнут. Скачайте готовый бриф.';}
}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function home(){
 const stats=boot.stats||{}, total=boot.cases.length;
 shell(`${heading('Сильная реклама начинается с ясной мысли.','Проверьте обещание, защитите идею и соберите бриф для рекламы.',B(I('plus')+' Новое дело','new','primary'))}<section class="hero" aria-labelledby="hero-title"><div class="hero-content"><div class="eyebrow"><span class="tiny-star">✳</span> СУД НАД ОБЕЩАНИЕМ</div><h1 id="hero-title">Вашу рекламу<br>можно <span>защитить?</span></h1><p>Лекс найдёт слабые места. Аврора сохранит идею. А последнее слово останется за вами.</p><div class="button-row">${B('Открыть первое дело '+I('arrow'),'demo','light','data-id="marketing"')}${B('Проверить свою фразу','new','ghost')}</div><div class="hero-note">${I('shield')}Без регистрации · Вы контролируете каждое решение</div></div><div class="hero-visual" aria-hidden="true"><div class="hero-case"><div class="case-label"><span>ДЕЛО 001 / УЧЕБНЫЙ ПРИМЕР</span>${I('scale')}</div><div class="quote">«Маркетинг,<br>который<br><mark>работает</mark>»</div><div class="hero-case-footer"><div class="initials"><i>Л</i><i>А</i><i>?</i></div><span>Обещание требует уточнения</span></div></div><div class="floating-note">${I('spark')}Не просто оценить. Сделать сильнее.</div></div></section><section class="progress-strip" aria-label="Три шага"><div class="progress-strip-item"><span class="step-number">01</span><div><strong>Принесите обещание</strong><p>Свою фразу или готовый пример</p></div></div><div class="progress-strip-item"><span class="step-number">02</span><div><strong>Выберите линию защиты</strong><p>Уточните пользу или основание</p></div></div><div class="progress-strip-item"><span class="step-number">03</span><div><strong>Заберите готовый бриф</strong><p>Для реального рекламного материала</p></div></div></section><div class="section-head"><div><h2>С чего начнём?</h2><p>Три учебных дела. Три разных слабых места.</p></div><a href="#/new" class="text-button">У меня своя фраза ${I('arrow')}</a></div><section class="cards">${DEMOS.slice(0,3).map((d,i)=>`<button class="sample-card" data-action="demo" data-id="${d.id}"><div class="sample-card-top"><span class="mono">ДЕЛО 00${i+1}</span><span class="tag">${esc(d.tag)}</span></div><h3>«${esc(d.claim)}»</h3><div class="sample-card-foot"><span>Открыть разбор</span>${I('arrow')}</div></button>`).join('')}</section><div class="home-bottom"><section class="card"><div class="section-head"><h3>Три точки зрения. Решение — ваше.</h3></div><div class="role-minis">${[['Л','Лекс','Проверяет обещание',''],['А','Аврора','Защищает идею','aurora'],['?','Свидетель','Задаёт простой вопрос','witness']].map(([letter,name,job,cls])=>`<div class="role-mini"><span class="role-avatar ${cls}">${letter}</span><div><strong>${name}</strong><small>${job}</small></div></div>`).join('')}</div><p class="source-note">Вымышленные редакторские роли. Сейчас используются сценарии и открытые правила, а не живой ИИ.</p></section><section class="card soft"><h3>Ваш след в JUDGE</h3><div class="activity-summary"><div><strong>${total}</strong><span>дел открыто</span></div><div><strong>${stats.verdict_issued||0}</strong><span>брифов выпущено</span></div><div><strong>${stats.witness_objection||0}</strong><span>возражений</span></div></div><a href="#/cases" class="text-button">Только реальные события ${I('arrow')}</a></section></div>`);
}
function field(name,label,value='',options={}){const {area=false,required=false,max=200,help='',full=false,type='text',placeholder=''}=options;return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}${required?' <span aria-hidden="true">*</span>':''}</label>${area?`<textarea id="f-${name}" name="${name}" maxlength="${max}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" maxlength="${max}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}">`}${help?`<small>${help}</small>`:''}</div>`;}
function newCase(){shell(`<div class="new-layout"><a href="#/" class="back">${I('back')}Рабочее пространство</a><span class="eyebrow">НОВОЕ ДЕЛО</span><h1>Какое обещание<br>будем защищать?</h1><p class="muted">Вставьте рекламную фразу. Мы найдём вопросы, которые стоит задать до публикации.</p><form id="new-form" class="card">${field('claim','Рекламная фраза','',{area:true,required:true,max:700,placeholder:'Например: «Лучший выбор для бизнеса»',help:'От 5 до 700 символов. Не вводите чужие персональные данные и коммерческие секреты.'})}<div class="form-grid">${field('product','Название продукта','',{max:100})}${field('audience','Для кого','',{max:160})}</div><div class="inline-error" role="alert" hidden></div><div class="form-actions"><span class="disclaimer">${I('shield')}Первый разбор без аккаунта.</span><button class="btn primary" type="submit">Начать рассмотрение ${I('arrow')}</button></div></form><div class="new-choices">${DEMOS.map(d=>`<button class="chip" data-action="demo" data-id="${d.id}">${esc(d.claim)}</button>`).join('')}</div></div>`,'Новое дело','cases');}
function stepper(s){const step={hearing:0,revision:1,review:2,ready:2,verdict:3,reopened:1}[s.phase];return `<div class="stepper" aria-label="Ход дела">${['Разбор','Защита','Формулировка','Бриф'].map((label,i)=>`<div class="stepper-item ${i===step?'active':i<step?'done':''}"><span>${i<step?'✓':i+1}</span>${label}</div>`).join('')}</div>`;}
function rolePanel(s){
 const last=current.events.filter(e=>e.type==='ai_commentary').at(-1);
 const comments=last?last.data.commentary:null;
 const roles=dialogue(s), role=roles.find(r=>r.role===selectedRole)||roles[0];
 return `<section class="role-panel"><div class="eyebrow">СОВЕТ РЕДАКТОРОВ</div><div class="role-tabs" role="group" aria-label="Выбор роли">${roles.map(r=>`<button class="role-tab ${r.role===selectedRole?'active':''}" data-action="role" data-role="${r.role}" aria-pressed="${r.role===selectedRole}">${r.name==='Свидетель 404'?'Свидетель':r.name}</button>`).join('')}</div><div class="speaker"><div class="role-avatar ${role.role==='lex'?'':role.role}">${role.role==='lex'?'Л':role.role==='aurora'?'А':'?'}</div><div><strong>${role.name}</strong><small>${role.job}</small></div></div><blockquote>${esc(role.text)}</blockquote><div class="role-panel-foot">Сценарная роль · не реальный эксперт</div>${comments?`<div class="ai-note"><strong>Последний комментарий ИИ</strong><p>${esc(comments[role.role])}</p><small>${date(last.at)} · может относиться к предыдущей версии дела</small></div>`:''}${boot.ai?.enabled?B(I('spark')+' Получить комментарий ИИ','ai','small full'):''}</section>`;
}
function auditCard(s){
  const x=current.comparison??comparison(s.claim,s.finalClaim,s.draft);
  const c=current.audit;
  return `<section class="card audit-card"><div class="section-head"><div><span class="eyebrow">РЕДАКТОРСКИЙ СЛЕД</span><h3>Что изменилось в формулировке</h3></div><span class="pill ${c?.consistent?'green':'amber'}">${c?.consistent?'История проверена':'Нужна проверка журнала'}</span></div><p class="panel-sub">Это поиск словарных сигналов, не юридическая или маркетинговая оценка.</p><div class="audit-columns"><div><span class="muted">Исходно</span><strong>${x.before.length} предупрежд.</strong></div><div><span class="muted">После редактирования</span><strong>${x.after.length} предупрежд.</strong></div></div>${x.resolved.length?`<p class="source-note">Больше не обнаружены: ${x.resolved.map(v=>esc(v.label)).join(', ')}.</p>`:''}${x.newWarnings.length?`<p class="source-note">Обратите внимание: ${x.newWarnings.map(v=>esc(v.label)).join(', ')}.</p>`:''}<p class="disclaimer">${esc(x.disclaimer)}</p><div class="button-row">${s.phase==='verdict'?B(I('download')+' Экспорт JSON-брифа','download-json','small'):''}</div></section>`;
}
function checks(s){const findings=analyze(s.finalClaim&&s.phase==='verdict'?s.finalClaim:s.claim,s.draft);return `<section class="checks card"><h3>Что видит JUDGE</h3>${findings.map(f=>`<div class="check-row"><span class="check-icon ${f.tone}">${I(f.tone==='ok'?'check':f.tone==='warning'?'alert':'file')}</span><div><strong>${esc(f.label)}</strong><p>${esc(f.detail)}</p></div></div>`).join('')}<div class="disclaimer">${I('shield')}Проверка по ограниченному набору правил. Баллов «эффективности» здесь нет.</div></section>`;}
function handoffHistory(){
 const items=current.handoffs||[];
 if(!items.length)return '';
 const now=Date.now();
 const status=h=>h.confirmed_actions>0?'Платформа подтвердила действие':h.redeemed_at?'Получено платформой':h.revoked_at?'Отозвано':h.mode==='clipboard'?'Подготовлен текст — доставку не подтверждаем':h.expires_at<=now?'Срок передачи истёк':'Ожидает получения платформой';
 return `<section class="card transfer-history"><div class="section-head"><div><h3>История передач</h3><p>Получение брифа и создание рекламы — разные события.</p></div>${I('link')}</div><div class="transfer-list">${items.slice(0,30).map(h=>`<div class="transfer-row"><div><strong>Платформа ${esc(h.platform_id)}</strong><small>${date(h.created_at)} · ${esc(status(h))}</small></div>${h.mode==='deeplink'&&!h.redeemed_at&&!h.revoked_at&&h.expires_at>now?B('Отозвать','handoff-revoke','small danger',`data-id="${esc(h.id)}"`):''}</div>`).join('')}</div><p class="source-note">Ручной экспорт нельзя отменить: текст уже мог быть скопирован. Открытие ссылки не является подтверждением рекламного действия.</p></section>`;
}
const ruCount=(n,one,few,many)=>`${n} ${n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many}`;
function comparisonRoom(s){
 const tests=current.comparisons||[];
 if(s.phase!=='verdict'&&!tests.length)return '';
 const server=boot.mode!=='preview';
 const rows=tests.map(t=>{
   const c=t.counts||{a:0,b:0,neither:0,total:0},n=c.total||0;
   const bar=(value,label,cls)=>`<div class="evidence-bar-row"><span>${label}</span><div class="evidence-bar"><span class="${cls}" style="width:${n?Math.round(value/n*100):0}%"></span></div><strong>${value}</strong></div>`;
   const status={open:'Приём ответов',expired:'Истёк срок',closed:'Закрыт автором',invalidated:'Прежняя версия'}[t.status]||'Завершён';
   return `<div class="evidence-study"><div class="section-head"><div><span class="eyebrow">СЛЕПОЙ ТЕСТ · ${esc(t.id.slice(0,8).toUpperCase())}</span><h4>${esc(status)}</h4></div><span class="pill">${ruCount(n,'ответ','ответа','ответов')}</span></div><div class="evidence-options"><div><small>А · Исходная версия</small><p>${esc(t.variantA)}</p></div><div><small>B · Вердикт</small><p>${esc(t.variantB)}</p></div></div>${bar(c.a,'Выбрали исходную','base')}${bar(c.b,'Выбрали итоговую','final')}${bar(c.neither,'Ни один вариант','neutral')}<p class="source-note">${esc(t.disclaimer)}</p><p class="source-note">Выдано ссылок: ${t.invites.total}; ожидают ответ: ${t.invites.active}; получено ответов: ${t.invites.answered}.</p>${t.status==='open'&&s.phase==='verdict'&&server?`<div class="button-row">${B(I('link')+' Пригласить читателя','comparison-invite','small primary',`data-id="${esc(t.id)}"`)}${B('Закрыть тест','comparison-close','small ghost',`data-id="${esc(t.id)}"`)}</div>`:''}${t.notes?.length?`<details class="evidence-notes"><summary>Комментарии участников · ${t.notes.length}</summary>${t.notes.map(x=>`<blockquote>${esc(x.note)}<small>${esc(x.selection==='a'?'Исходная':x.selection==='b'?'Итоговая':'Ни один вариант')} · ${date(x.at)}</small></blockquote>`).join('')}</details>`:''}</div>`;
 }).join('');
 return `<section class="card evidence-room"><div class="section-head"><div><span class="eyebrow">EVIDENCE ROOM / JUDGE</span><h3>Проверка понятности на людях</h3><p>Разные люди увидят два рекламных текста в меняющемся порядке — без отметки «до» и «после».</p></div>${I('users')}</div><p class="notice">Только предпочтение приглашённых читателей. Это не эксперимент по продажам, не показатель CTR и не научное доказательство эффективности.</p>${s.phase==='verdict'&&server?`<div class="button-row">${B(I('plus')+' Создать слепой тест','comparison-start','primary')}</div>`:''}${!server?'<p class="source-note">Слепые тесты работают в серверной версии; автономное превью не собирает чужие ответы.</p>':''}${rows||'<p class="source-note">Пока нет тестов. Зафиксируйте фразу и отправьте её знакомым без подсказки, какая версия новая.</p>'}</section>`;
}
function compareInvite(data,raw){
 shell(`<div class="comparison-public"><span class="eyebrow">EVIDENCE ROOM · НЕЗАВИСИМЫЙ ЧИТАТЕЛЬ</span><h1>Какая реклама<br>понятнее?</h1><p class="muted">${esc(data.disclosure)}</p><form class="card" id="compare-form" data-token="${esc(raw)}"><h2>${esc(data.question)}</h2><div class="compare-options"><label class="compare-choice"><input type="radio" name="choice" value="first" required><span class="compare-key">01</span><span class="compare-text">${esc(data.first)}</span><span class="compare-hint">Выбрать этот вариант</span></label><label class="compare-choice"><input type="radio" name="choice" value="second"><span class="compare-key">02</span><span class="compare-text">${esc(data.second)}</span><span class="compare-hint">Выбрать этот вариант</span></label><label class="compare-choice none"><input type="radio" name="choice" value="neither"><span class="compare-key">—</span><span class="compare-text">Ни один вариант не понятен</span></label></div>${field('note','Почему выбрали именно так? (по желанию)','',{area:true,max:500,help:'До 500 символов. Не пишите личные данные. Ответ увидит автор текста.'})}<label class="checkbox"><input type="checkbox" name="accepted" required><span>Я добровольно отправляю выбор и, если указал, комментарий автору рекламы.</span></label><div class="inline-error" role="alert" hidden></div><button class="btn primary full" type="submit">Отправить ответ ${I('arrow')}</button><p class="source-note">Ответ можно отправить один раз. Регистрация не нужна. Срок ссылки: ${date(data.expiresAt)}.</p></form></div>`,'Слепой тест','cases');
}
function history(){return `<details class="card timeline-card"><summary class="section-toggle"><h3>История решений</h3><span class="pill">${current.events.length} событий</span></summary><ol class="timeline">${current.events.map((e,i)=>`<li><span class="event-dot"></span><div><strong>${EVENT_NAMES[e.type]||esc(e.type)}</strong><small>${date(e.at)}</small></div><span class="event-index">${String(i+1).padStart(2,'0')}</span></li>`).join('')}</ol><p class="source-note">Это сохранённые события вашего дела. Мы не сочиняем действия других пользователей.</p></details>`;}
function renderCase({preserveScroll=false}={}){
 const previousScroll=window.scrollY;
 const s=current.state;
 const isOwnerRevision=s.phase==='reopened'&&current.events.filter(e=>['case_reopened','owner_reopen'].includes(e.type)).at(-1)?.type==='owner_reopen';
 const cinema=current.cinemaImport;
 const originPanel=cinema?`<section class="card cinema-origin"><span class="eyebrow">ИСТОЧНИК · ADVERSE CINEMA</span><h3>Ваше решение из интерактивного фильма</h3><p class="panel-sub">Текст из фильма сохранён как предложение. Доказательства и вердикт ещё не проверены сервером JUDGE.</p><div class="cinema-import-pair"><div><small>ПРЕДЛОЖЕННЫЙ ТЕКСТ</small><p>${esc(cinema.proposedClaim)}</p></div><div><small>ВЫБРАННЫЙ ПУТЬ</small><p>${esc(cinema.strategy||'Не указан')}</p><small>ОСНОВАНИЯ</small><p>${esc(cinema.evidenceStatus==='user_supplied_unverified'?'Указаны автором; не проверены':cinema.evidenceStatus==='missing'?'Не предоставлены':'Не обозначены')}</p></div></div>${cinema.evidenceText?`<details><summary>Описание источника</summary><p>${esc(cinema.evidenceText)}</p></details>`:''}<p class="source-note">Следующий шаг — выбрать действие и заполнить реальную информацию о продукте. Старый киношный вердикт не импортируется.</p></section>`:'';
 const quote=`<section class="quote-box"><div class="eyebrow">ИСХОДНОЕ ОБЕЩАНИЕ</div><blockquote>«${esc(s.claim)}»</blockquote></section>`;
 let body='';
 if(s.phase==='hearing')body=`${quote}<section class="card"><h2 class="panel-title">Как будем защищать идею?</h2><p class="panel-sub">Выберите действие. Не нужно угадывать «правильный» ответ.</p><div class="action-grid">${ACTIONS.map(a=>`<button class="action-card" data-action="choose" data-id="${a.id}"><span class="action-symbol">${I(a.icon)}</span><span class="action-copy"><strong>${a.title}</strong><small>${a.subtitle}</small></span>${I('arrow')}</button>`).join('')}</div><div class="disclaimer">${I('scale')}Решение определяет следующий шаг, а не скрытый рейтинг.</div></section>`;
 if(s.phase==='revision')body=`${quote}<section class="card"><h2 class="panel-title">${esc(ACTIONS.find(a=>a.id===s.action)?.title)}</h2><p class="panel-sub">Запишите то, что продукт действительно умеет. Мы не добавим несуществующие функции.</p><form id="brief-form"><div class="form-grid">${field('product','Продукт',s.draft.product,{required:true,max:100})}${field('audience','Кому он нужен',s.draft.audience,{required:true,max:160})}${field('fact','Что человек может сделать',s.draft.fact,{area:true,required:true,max:500,full:true,placeholder:'Например: «Собирайте заметки в одном рабочем кабинете»',help:'Факт со слов автора. Не вставляйте обещания, которые не можете подтвердить.'})}${field('problem','Вопрос или задача клиента',s.draft.problem,{max:240})}${field('cta','Призыв к действию',s.draft.cta||'Посмотреть продукт',{required:true,max:100})}${field('evidence',s.action==='evidence'?'Основание и условия применения':'Основание (необязательно)',s.draft.evidence,{area:true,required:s.action==='evidence',max:1000,full:true,help:'Источник не проверяется автоматически. Не выдавайте пример за гарантию результата.'})}${field('source','Ссылка на источник',s.draft.source,{type:'url',max:500,full:true,placeholder:'https://',help:'Только HTTPS. JUDGE не открывает эту ссылку и не загружает её содержимое.'})}</div><div class="inline-error" role="alert" hidden></div><div class="form-actions">${B(I('back')+' Другая линия защиты','change','ghost')}<button class="btn primary" type="submit">Собрать формулировки ${I('arrow')}</button></div></form></section>`;
 if(s.phase==='review'||s.phase==='ready'){
  if(!s.candidates.some(v=>v.id===selectedVariant))selectedVariant=s.candidates[0]?.id;
  const chosen=s.candidates.find(v=>v.id===selectedVariant);
  body=`<section class="card"><span class="eyebrow">НОВАЯ ФОРМУЛИРОВКА</span><h2 class="panel-title top-gap">Три подхода. Ваше последнее слово.</h2><p class="panel-sub">Это шаблонные варианты на основе ваших данных — не заключение об эффективности.</p><div role="group" aria-label="Варианты формулировки">${s.candidates.map((v,i)=>`<button class="variant ${v.id===selectedVariant?'active':''}" data-action="variant" data-id="${v.id}" aria-pressed="${v.id===selectedVariant}"><span class="variant-radio">${String.fromCharCode(65+i)}</span><div><strong>${v.label} <small class="muted">· ${v.description}</small></strong><p>${esc(v.text)}</p></div></button>`).join('')}</div><form id="verdict-form">${field('claim','Отредактируйте итоговый текст',chosen?.text,{area:true,required:true,max:1000,full:true})}${current.cinemaImport?`<div class="cinema-import-tip">${B('Вставить предложение из фильма','cinema-fill','ghost')}<small>Измените формулировку и проверьте основания перед фиксацией.</small></div>`:''}<label class="checkbox"><input type="checkbox" name="acknowledged" required><span>Я понимаю, что факты не проверены автоматически. Перед публикацией я проверю формулировку и основания.</span></label><div class="inline-error" role="alert" hidden></div><div class="form-actions">${B('Изменить исходные данные','change','ghost')}<button type="submit" class="btn primary">Зафиксировать бриф ${I('check')}</button></div></form></section>`;
 }
 if(s.phase==='verdict'||s.phase==='reopened'){
 body=`<div class="verdict-banner"><span class="verdict-seal">${I(s.phase==='reopened'?'users':'check')}</span><div><span class="eyebrow">${s.phase==='reopened'?'НОВОЕ СОБЫТИЕ':'ДЕЛО РАССМОТРЕНО'}</span><h2>${s.phase==='reopened'?(isOwnerRevision?'Вы открыли пересмотр своей идеи.':'Свидетель оспорил формулировку.'):'Ваша идея готова к следующему шагу.'}</h2><p>${s.phase==='reopened'?(isOwnerRevision?'Предыдущая версия сохранена, можете выбрать новую линию защиты.':'Это настоящее возражение, полученное по приглашению.'):'Редакторский бриф собран. Это не разрешение на публикацию.'}</p></div></div><div class="comparison"><section class="card"><span class="eyebrow">БЫЛО</span><h3>Исходное обещание</h3><p>${esc(s.claim)}</p></section><section class="card after"><span class="eyebrow">СТАЛО</span><h3>Ваша формулировка</h3><p>${esc(s.finalClaim)}</p></section></div><section class="card"><h3>Бриф для реального материала</h3><div class="brief-meta"><div><small>ПРОДУКТ</small><p>${esc(s.draft.product)}</p></div><div><small>АУДИТОРИЯ</small><p>${esc(s.draft.audience)}</p></div><div><small>ДЕЙСТВИЕ</small><p>${esc(s.draft.cta)}</p></div><div><small>СТАТУС ФАКТОВ</small><p>Со слов автора · не проверены</p></div></div><div class="button-row">${B(I('copy')+' Скопировать бриф','copy-brief','primary')}${B(I('download')+' Скачать .txt','download','')}${s.phase==='verdict'?B(I('link')+' Передать на платформу','handoff',''):''}</div></section>`;
 if(s.phase==='reopened'&&current.events.filter(e=>['case_reopened','owner_reopen'].includes(e.type)).at(-1)?.type==='case_reopened')body+=`<section class="card objection-card"><span class="eyebrow">ВОЗРАЖЕНИЕ СВИДЕТЕЛЯ</span><p class="objection-text">${esc(s.objections.at(-1)?.text)}</p><form id="defend-form">${field('text','Ваш ответ', '',{area:true,required:true,max:1000,help:'От 10 символов. Ответ сохраняется в истории; он не доказывает вашу правоту.'})}<div class="inline-error" role="alert" hidden></div><div class="form-actions">${B('Принять и уточнить фразу','change','')}<button class="btn primary" type="submit">Сохранить ответ</button></div></form></section>`;
 else if(s.phase==='reopened')body+=`<section class="card"><h3>Вы открыли редакторский пересмотр</h3><p class="panel-sub">Исходный приговор остаётся в истории. Выберите линию защиты, подготовьте новую версию и выпустите новый бриф.</p>${B('Выбрать способ улучшения','change','primary')}</section>`;
 else body+=`<section class="card"><div class="section-head"><div><h3>Сильную идею полезно оспорить.</h3><p>Пригласите человека, который заметит то, что вы пропустили.</p></div>${I('users')}</div><div class="button-row">${B('Вызвать свидетеля '+I('arrow'),'invite','dark')}${B('Управлять приглашениями','invites','ghost')}${B('Пересмотреть свою версию','reopen','ghost')}${B(I('refresh')+' Обновить дело','refresh','ghost')}</div>${!boot.user?`<p class="source-note">Дело уже сохранено в гостевой сессии. ${B('Создать аккаунт для входа с другого устройства','account','small ghost')}</p>`:''}</section>`;
 }
 shell(`${heading(`Дело ${esc(s.id.slice(0,8).toUpperCase())}`,`${phaseName(s.phase)} · ${date(s.updatedAt)}`,`<a href="#/cases" class="btn ghost">${I('folder')}Мои дела</a>`)}${stepper(s)}<div class="case-layout"><div class="case-body">${originPanel}${body}${['verdict','reopened'].includes(s.phase)?comparisonRoom(s)+studio.caseTools(s,current.comparisons)+auditCard(s)+handoffHistory():''}${history()}</div><aside class="case-aside">${rolePanel(s)}${checks(s)}</aside></div>`,'Рассмотрение дела','cases');
 if(preserveScroll)window.scrollTo(0,previousScroll);else {document.querySelector('#main')?.focus({preventScroll:true});window.scrollTo(0,0);}
}
function analyticsView(data){
 const max=Math.max(1,data.funnel?.[0]?.count||0);
 const stages=(data.funnel||[]).map(s=>`<div class="funnel-line"><div class="funnel-name"><strong>${esc(s.label)}</strong><span>${s.count} · ${s.rate}% от начавших</span></div><div class="funnel-rail"><span style="width:${Math.max(0,Math.min(100,100*s.count/max))}%"></span></div></div>`).join('');
 const days=(data.series||[]).map(d=>`<div class="day-bar" title="${esc(d.day)}: новых дел ${d.newCases}, брифов ${d.verdicts}"><span style="height:${Math.min(100,(d.verdicts/Math.max(1,...data.series.map(x=>x.verdicts)))*100)}%"></span><small>${d.day.slice(8)}</small></div>`).join('');
 shell(`${heading('Аналитика без выдуманных цифр','Только действия, зафиксированные сервером JUDGE.')}<div class="kpi-grid"><section class="card"><small>Открыто дел</small><h2>${data.funnel?.[0]?.count||0}</h2><p>Уникальные дела</p></section><section class="card"><small>Выпущено брифов</small><h2>${data.funnel?.[3]?.count||0}</h2><p>Хотя бы один вердикт</p></section><section class="card"><small>Подтверждений платформы</small><h2>${data.funnel?.[6]?.count||0}</h2><p>Только проверенные события</p></section><section class="card"><small>Возражений свидетелей</small><h2>${data.social?.objected||0}</h2><p>Число дел с возражением</p></section></div><div class="analytics-layout"><section class="card"><h3>Воронка по событиям</h3><p class="panel-sub">Каждое дело учитывается только один раз в каждой строке. Повторные версии не раздувают воронку.</p>${stages||'<p>Событий пока нет.</p>'}</section><section class="card"><h3>Брифы по дням</h3><p class="panel-sub">Последние 14 дней, количество выпущенных версий</p><div class="day-chart">${days}</div><div class="metric-split"><span>Приглашали свидетелей</span><strong>${data.social?.invited||0}</strong></div><div class="metric-split"><span>Пересматривали по инициативе автора</span><strong>${data.social?.ownerReopened||0}</strong></div></section></div><p class="notice top-gap">${esc(data.disclaimer)}</p>`,'Аналитика','analytics');
}
function cases(){const list=boot.cases;shell(`${heading('Мои дела','История ваших решений. Никаких выдуманных показателей.',B(I('plus')+' Новое дело','new','primary'))}${list.length?`<div class="toolbar"><input class="search-input" id="case-search" type="search" placeholder="Поиск по рекламной фразе" aria-label="Поиск дел"><span class="pill">Всего: ${list.length}</span></div><div class="cases-list">${list.map(s=>`<a href="#/case/${s.id}" class="case-list-row" data-search="${esc((s.claim+' '+(s.finalClaim||'')).toLowerCase())}"><span class="case-list-icon">${I(s.phase==='reopened'?'users':'scale')}</span><div class="case-list-title"><h3>${esc(s.claim)}</h3><p>${esc(s.draft.product||'Продукт ещё не указан')} · ${date(s.updatedAt)}</p></div><span class="pill ${s.phase==='verdict'?'green':s.phase==='reopened'?'amber':'purple'}">${phaseName(s.phase)}</span>${I('arrow')}</a>`).join('')}</div><p id="no-matches" class="notice" hidden>По вашему запросу дел нет.</p>`:`<div class="empty card">${I('folder')}<h2>Первое дело — впереди.</h2><p>Вставьте рекламную фразу или начните с учебного примера. Результат сохранится здесь.</p>${B('Начать с примера '+I('arrow'),'demo','primary','data-id="marketing"')}</div>`}`,'Мои дела','cases');}
function platforms(){
 const count=boot.platforms.filter(p=>p.configured).length;
 shell(`${heading('Семь платформ. Один понятный бриф.','Проверка подключения по техническому контракту, без приписывания сайтам неизвестных функций.')}<div class="notice amber">${I('shield')}Из ${boot.platforms.length} конфигураций к подписанной передаче подготовлено ${count}. Даже готовый контракт не означает, что реальный сайт прошёл приёмочный тест.</div><div class="platform-grid">${boot.platforms.map(p=>`<section class="platform-card"><span class="platform-letter">${esc(p.id)}</span><div class="platform-info"><h3>${esc(p.name||'Платформа '+p.id)}</h3><p>${p.configured?'Подписанный протокол готов. Требуется испытание на стороне платформы.':esc((p.reasons||[]).join(' · ')||'Не подключена')}</p><span class="pill ${p.configured?'green':'amber'}">${p.configured?'Контракт готов, не проверен на сайте':'Ручной режим / не подключена'}</span></div></section>`).join('')}</div><section class="card top-gap"><h3>Что нужно для настоящего подключения</h3><p class="panel-sub">Проверенный HTTPS-адрес → согласованный контракт → отдельный серверный секрет → тест одноразового получения → подтверждённое действие. Оператор может запустить <code>npm run integrations:check</code>.</p><a href="#/cases" class="btn">${I('folder')}Открыть свои брифы</a></section>`,'Платформы','platforms');
}
function method(){shell(`${heading('Как работает JUDGE','Не чат и не машина истины. Процесс, в котором каждое решение имеет след.')}<section class="card privacy-text"><h2>Смысл важнее печати.</h2><p>Принесите рекламное обещание. Лекс задаёт неудобные вопросы, Аврора сохраняет эмоциональную силу, Свидетель смотрит на текст глазами покупателя. Решение всегда принимаете вы.</p><h3>Три пути защиты</h3><p>Уточнить обещание — назвать конкретную пользу. Предъявить основание — записать источник и условия. Изменить подход — начать с задачи или вопроса вместо гарантии.</p><h3>Что действительно проверяется</h3><p>В сценарном режиме правила ищут некоторые абсолютные слова, числовые обещания и размытые формулировки. Они могут ошибаться и пропускать проблемы. Здесь нет баллов законности, предсказаний конверсии или симуляции мнения настоящей аудитории.</p><h3>Что сохраняется</h3><p>Исходная фраза, выбранное действие, введённые вами факты, новый текст, версии и события. Серверная база хранит и состояние, и журнал. При перезагрузке история не меняется.</p><h3>Слепое сравнение (Evidence Room)</h3><p>Для действующего вердикта можно провести простой тест понятности: пригласить разных читателей по индивидуальным одноразовым ссылкам и сравнить выбор до/после. Порядок вариантов меняется. Это добровольный нерепрезентативный опрос, а не проверка CTR, продаж или юридической точности.</p><h3>Зачем нужен свидетель</h3><p>Вы выдаёте одноразовую ссылку на итоговую фразу и аудиторию. Другой человек пишет возражение. Сервер действительно открывает ваше дело повторно. Внутренние основания и исходный текст свидетелю не показываются.</p><h3>Где начинается настоящий продукт</h3><p>Бриф можно забрать бесплатно, без регистрации. Подключение к вашим семи платформам требует проверки их API. До этого передача остаётся копированием, а подтверждённые действия не рисуются из воздуха.</p><div class="notice">${I('scale')}Все персонажи вымышлены. Это редакторская помощь, не юридическая экспертиза.</div><a href="#/new" class="btn primary top-gap">Проверить свою фразу ${I('arrow')}</a></section>`,'Как это работает','method');}
function settings(){shell(`${heading('Ваши данные и настройки','Прозрачность важнее иллюзии всезнания.')}<div class="settings-grid"><section class="card"><h3>Доступ</h3><div class="setting-line"><span>Статус</span><strong>${boot.user?'Аккаунт':'Гостевая сессия'}</strong></div><div class="setting-line"><span>Хранение</span><strong>${boot.mode==='preview'?'Этот браузер':'Локальная SQLite'}</strong></div><p class="panel-sub">${boot.mode==='preview'?'Превью не заменяет сервер. Локальные данные браузера не защищены авторизацией.':'Гостевая сессия действует семь дней. Для входа с другого устройства создайте локальный аккаунт. Подтверждение email и восстановление пароля работают только при настроенном почтовом провайдере.'}</p><div class="button-row">${B(boot.user?'Выйти':'Создать аккаунт / войти',boot.user?'logout':'account','primary')}${boot.user&&boot.mode!=='preview'?B(I('shield')+' Активные сеансы','sessions','',''):''}${boot.user&&boot.mode!=='preview'?B('Сменить пароль','change-password','',''):''}${boot.user&&boot.mode!=='preview'?B(boot.user.emailVerified?'Почта подтверждена':'Подтвердить email','settings-verify','ghost'):''}</div></section><section class="card"><h3>Роли и ИИ</h3><div class="setting-line"><span>Сценарные роли</span><strong>Работают</strong></div><div class="setting-line"><span>Внешний ИИ</span><strong>${boot.ai?.enabled?'Настроен':'Не подключён'}</strong></div><p class="panel-sub">Внешний ИИ вызывается только после отдельного согласия внутри дела. Ключ хранится на сервере. Модель комментирует текст, но не изменяет решения и события.</p><span class="pill">${boot.ai?.enabled?esc(boot.ai.model):'Нет платных запросов по умолчанию'}</span></section><section class="card"><h3>Экспорт и удаление</h3><p class="panel-sub">Получите JSON с делами и историей или удалите данные текущей сессии/аккаунта из активной базы. Удалённые данные могут оставаться во внешних резервных копиях оператора.</p><div class="button-row">${B(I('download')+' Выгрузить данные','export-data','')}${B(I('trash')+' Удалить мои данные','delete-data','danger')}</div></section><section class="card"><h3>Готовность к публикации</h3><p class="panel-sub">Это локальный пилот. Для публичного запуска ещё нужны производственная авторизация, резервное копирование, согласованная политика хранения, мониторинг и проверенные подключения.</p><button class="text-button" data-action="privacy">Как обрабатываются данные ${I('arrow')}</button></section></div>`,'Настройки','settings');}
function witness(data,token){shell(`<div class="witness-layout"><span class="eyebrow">ВЫ ПРИГЛАШЕНЫ КАК СВИДЕТЕЛЬ</span><h1>Найдите слабое место.<br>Измените ход дела.</h1><p class="muted">${esc(data.disclosure)}</p><div class="quote-box"><span class="eyebrow">ФРАЗА, КОТОРУЮ НУЖНО ОСПОРИТЬ</span><blockquote>«${esc(data.claim)}»</blockquote><span class="pill">Для: ${esc(data.audience)}</span></div><form id="witness-form" data-token="${esc(token)}" class="card">${field('text','Что в этой фразе стоит уточнить?','',{area:true,required:true,max:1000,placeholder:'Мне непонятно, что именно я получу…',help:'От 10 до 1000 символов. Одно приглашение — одно возражение.'})}<label class="checkbox"><input type="checkbox" required><span>Моё возражение будет показано автору. Я не включаю личные данные или конфиденциальные сведения.</span></label><div class="inline-error" role="alert" hidden></div><button type="submit" class="btn primary full">Отправить возражение ${I('arrow')}</button><p class="source-note">Ссылка действительна до ${date(data.expiresAt)}. Регистрация не нужна.</p></form></div>`,'Свидетель','cases');}
async function render(){
 const ticket=++viewToken, path=route();current=null;
 try {
  await syncBoot();if(ticket!==viewToken)return;
  if(path==='/')home();else if(path==='/new')newCase();else if(path==='/analytics'){const data=await client.request('/analytics');if(ticket!==viewToken)return;analyticsView(data);return;}
  else if(path==='/cases')cases();else if(path==='/workspaces')await studio.listWorkspaces();else if(path.startsWith('/workspace-invite/'))await studio.invitation(path.slice(18));else if(path.startsWith('/workspace/'))await studio.workspace(path.slice(11));else if(path==='/campaigns')await production.list();else if(path.startsWith('/campaign/'))await production.detail(path.slice(10));else if(path.startsWith('/ops/'))await advanced.detail(path.slice(5));else if(path.startsWith('/governance-workspace/'))await governance.portfolio(path.slice(22));else if(path.startsWith('/governance/'))await governance.detail(path.slice(12));else if(path.startsWith('/next/'))await waves.detail(path.slice(6));else if(path==='/research')await studio.studies();else if(path.startsWith('/research/'))await studio.study(path.slice(10));else if(path==='/platforms')platforms();else if(path==='/settings')settings();else if(path==='/method')method();
  else if(path.startsWith('/case/')){const detail=await client.detail(path.slice(6));if(ticket!==viewToken)return;current=detail;selectedVariant='';renderCase();}
  else if(path.startsWith('/witness/')){const token=path.slice(9);const data=await client.request('/witness/'+encodeURIComponent(token));if(ticket!==viewToken)return;witness(data,token);}
  else if(path.startsWith('/compare/')){const token=path.slice(9);const data=await client.request('/compare/'+encodeURIComponent(token));if(ticket!==viewToken)return;compareInvite(data,token);}
  else shell(`<div class="empty card"><h2>Эта страница не найдена.</h2><a href="#/" class="btn primary">Вернуться в JUDGE</a></div>`);
  document.title=`${path.startsWith('/case/')?'Дело · ':''}JUDGE — ADVERSE`;
 }catch(e){if(ticket!==viewToken)return;if(!boot)app.innerHTML=`<main class="error-box"><h2>Не удалось открыть JUDGE</h2><p>${esc(e.message)}</p>${B('Повторить','refresh','primary')}</main>`;else shell(`<div class="error-box"><h2>Не удалось открыть страницу</h2><p>${esc(e.message)}</p><a href="#/" class="btn primary">На главную</a></div>`);}
}
async function command(action,body={}){if(!current)throw new Error('Дело не открыто.');const result=await client.command(current.state.id,action,{commandId:clientUUID(),expectedVersion:current.state.version,...body});current=result;return result;}
function authForm(mode='register'){
 if(boot.mode==='preview'){showModal('В серверной сборке',`<p class="modal-sub">Аккаунты и вход доступны после запуска сервера. В этом HTML-превью данные остаются в браузере, без защиты аккаунтом.</p>`);return;}
 if(boot.user){navigate('/settings');return;}
 showModal(mode==='register'?'Сохраните свой след':'С возвращением',`<p class="modal-sub">Локальный аккаунт сохраняет доступ к вашим делам с другого устройства. Сам бриф доступен и без регистрации.</p><div class="modal-tabs">${B('Создать аккаунт','auth-tab',mode==='register'?'primary':'','data-mode="register"')}${B('Войти','auth-tab',mode==='login'?'primary':'','data-mode="login"')}</div><form id="auth-form" data-mode="${mode}" class="modal-form">${field('email','Email','',{required:true,type:'email',max:254})}${field('password','Пароль','',{required:true,type:'password',max:128,help:mode==='register'?'От 12 до 128 символов. Восстановление пароля доступно после настройки почтового провайдера.':''})}${mode==='register'?'<label class="checkbox"><input type="checkbox" name="accepted" required><span>Понимаю ограничения локального пилота: проверка почты требует отдельной настройки провайдера. Не использую пароль от других сервисов.</span></label>':''}<div class="inline-error" role="alert" hidden></div><button class="btn primary full" type="submit">${mode==='register'?'Создать аккаунт':'Войти'}</button></form>${mode==='login'?B('Забыли пароль?','auth-recovery','ghost full'):''}<p class="source-note">Это аккаунт JUDGE, не общая учётная запись семи платформ.</p>`);
 modal.querySelector('[name=email]').autocomplete='email';modal.querySelector('[name=password]').autocomplete=mode==='register'?'new-password':'current-password';
}
function privacy(){showModal('Что происходит с данными',`<div class="privacy-text"><p>Фразы, факты, решения и возражения сохраняются в локальной серверной базе (в автономном превью — в браузере). Гостевой доступ связан с cookie сроком на семь дней.</p><p>По умолчанию нет внешней аналитики, рекламных трекеров, живых запросов ИИ или автоматической отправки на семь платформ.</p><p>По ссылке слепого теста доступны две формулировки; участник может передать автору текстовый комментарий. По ссылке свидетеля доступны только итоговая фраза и аудитория. Любой владелец ссылки сможет их прочитать до отзыва или истечения срока.</p><p>При запросе внешнего ИИ указанное содержание дела передаётся провайдеру после отдельного согласия. Отказ не блокирует сценарный разбор.</p><p>Доступны экспорт и удаление из активной базы. Для публичной эксплуатации оператор должен установить политику хранения, работу с резервными копиями и порядок обращений. Соответствие GDPR или другим законам этой сборкой не заявляется.</p></div>`);}
async function onAction(button){
 const a=button.dataset.action;
 if(a.startsWith('next-')){await waves.action(a,button);return;}
 if(a.startsWith('gov-')){await governance.action(a,button);return;}
 if(a.startsWith('ops-')){await advanced.action(a,button);return;}
 if(a.startsWith('prod-')){await production.action(a,button);return;}
 if(a.startsWith('studio-')){await studio.action(a,button);return;}
 if(a==='close')return closeModal();if(a==='menu'){const el=document.querySelector('#sidebar');el.classList.toggle('open');button.setAttribute('aria-expanded',el.classList.contains('open'));return;}
 if(a==='settings-verify'){if(boot.user.emailVerified)return toast('Почта уже подтверждена.');showModal('Подтвердить email',`<p class="modal-sub">Письмо с одноразовым кодом. Внешний почтовый провайдер должен быть настроен.</p>${B('Отправить код','settings-verify-request','ghost full')}<form id="settings-verify-form"><label>Код из письма</label><input name="code" required maxlength="100"><div class="inline-error" hidden role="alert"></div><button class="btn primary full" type="submit">Подтвердить</button></form>`);return;}
 if(a==='auth-recovery'){showModal('Восстановить пароль',`<p class="modal-sub">Если аккаунт существует, мы отправим одноразовый код. Ответ не раскрывает, зарегистрирован ли адрес.</p><form id="auth-recovery-request-form"><label>Email</label><input name="email" type="email" required maxlength="254"><div class="inline-error" role="alert" hidden></div><button type="submit" class="btn primary full">Запросить код</button></form><form id="auth-recovery-confirm-form"><label>Код восстановления</label><input name="code" required><label>Новый пароль (не менее 12 символов)</label><input name="newPassword" type="password" minlength="12" required><div class="inline-error" role="alert" hidden></div><button type="submit" class="btn ghost full">Сменить пароль</button></form>`);return;}
 if(a==='settings-verify-request'){await client.request('/auth/verify/request',{method:'POST',body:{}});toast('Письмо отправлено.');return;}
 if(a==='privacy')return privacy();if(a==='new')return navigate('/new');if(a==='account')return authForm();if(a==='auth-tab'){closeModal();return authForm(button.dataset.mode);}
 if(a==='role'){selectedRole=button.dataset.role;renderCase({preserveScroll:true});document.querySelector(`[data-role="${selectedRole}"]`)?.focus();return;}
 if(a==='cinema-fill'){const field=document.querySelector('#verdict-form [name=claim]');if(field&&current?.cinemaImport){field.value=current.cinemaImport.proposedClaim;field.focus();toast('Текст вставлен. Проверьте факты и условия.');}return;}
 if(a==='variant'){selectedVariant=button.dataset.id;const v=current.state.candidates.find(v=>v.id===selectedVariant);document.querySelector('[name=claim]').value=v.text;document.querySelectorAll('.variant').forEach(b=>{b.classList.toggle('active',b.dataset.id===selectedVariant);b.setAttribute('aria-pressed',b.dataset.id===selectedVariant);});return;}
 if(a==='refresh')return render();
 if(a==='demo'){const d=DEMOS.find(d=>d.id===button.dataset.id);const result=await client.create({claim:d.claim,draft:d});return navigate('/case/'+result.state.id);}
 if(a==='choose'){await command('action',{action:button.dataset.id});renderCase();return;}
 if(a==='change'){showModal('Выберите линию защиты',`<div class="action-grid">${ACTIONS.map(x=>B(I(x.icon)+' '+x.title,'modal-choose','','data-id="'+x.id+'"')).join('')}</div>`);return;}
 if(a==='modal-choose'){await command('action',{action:button.dataset.id});closeModal();renderCase();return;}
 if(a==='reopen'){showModal('Пересмотреть бриф?',`<p class="modal-sub">Вы сможете переписать рекламную формулировку. Предыдущий приговор сохранится в журнале, а действующие приглашения на старую версию будут отозваны.</p>${B('Открыть пересмотр','confirm-reopen','primary full')}`);return;}
 if(a==='confirm-reopen'){await command('reopen');closeModal();renderCase();return;}
 if(a==='download-json')return download('JUDGE-'+current.state.id.slice(0,8)+'-brief.json',JSON.stringify({...makeBrief(current.state),comparison:comparison(current.state.claim,current.state.finalClaim,current.state.draft),integrity:current.audit},null,2),'application/json');
 if(a==='copy-brief')return copy(briefText(current.state));
 if(a==='download')return download('JUDGE-'+current.state.id.slice(0,8)+'.txt',briefText(current.state));
 if(a==='comparison-start'){
  if(boot.mode==='preview')return showModal('Только серверный режим','<p>В локальном HTML нельзя собирать ответы других людей.</p>');
  return showModal('Новый слепой тест',`<p class="modal-sub">Мы покажем исходную и итоговую формулировки приглашённым людям. Они не узнают, где новый текст. Не отправляйте конфиденциальные фразы.</p><form id="comparison-start-form"><label class="checkbox"><input type="checkbox" required name="consent"><span>Разрешаю показать две формулировки любому владельцу индивидуальной ссылки.</span></label><div class="inline-error" role="alert" hidden></div><button class="btn primary full" type="submit">Создать тест понятности</button></form>`);
 }
 if(a==='comparison-invite'){
  const result=await command('comparison-invite',{comparisonId:button.dataset.id});
  const link=location.origin+location.pathname+'#/compare/'+result.comparisonInvite.token;
  renderCase({preserveScroll:true});
  showModal('Личная ссылка участника',`<p class="modal-sub">Одна ссылка — один ответ. Создавайте отдельную ссылку для каждого участника; порядок вариантов будет сбалансирован.</p><textarea class="link-box" readonly>${esc(link)}</textarea>${B(I('copy')+' Скопировать ссылку','copy-invite','primary full')}<p class="source-note">Ссылка хранится только у вас. Любой владелец ссылки может увидеть оба текста, пока тест открыт.</p>`);
  return;
 }
 if(a==='comparison-close'){
  return showModal('Закрыть сбор ответов?',`<p class="modal-sub">Новые ответы больше не будут приниматься. Уже полученные выборы сохранятся в истории.</p>${B('Закрыть тест','comparison-close-confirm','danger full',`data-id="${esc(button.dataset.id)}"`)}`);
 }
 if(a==='comparison-close-confirm'){
  await command('comparison-close',{comparisonId:button.dataset.id});closeModal();renderCase();toast('Тест закрыт. Результаты сохранены.');return;
 }
 if(a==='invite'){
  if(boot.mode==='preview')return showModal('Приглашения — в серверной версии','<p class="modal-sub">Автономный файл не может передавать возражения между людьми. Запустите серверную сборку из архива.</p>');
  showModal('Вызвать свидетеля',`<p class="modal-sub">Свидетель увидит итоговую фразу и аудиторию. Внутренние материалы не раскрываются. Ссылка одноразовая и действует семь дней.</p><form id="invite-form"><label class="checkbox"><input type="checkbox" required name="consent"><span>Разрешаю показывать итоговую фразу и аудиторию любому, у кого есть эта ссылка.</span></label><div class="inline-error" role="alert" hidden></div><button class="btn primary full" type="submit">Создать приглашение</button></form>`);return;
 }
 if(a==='copy-invite')return copy(modal.querySelector('textarea').value);
 if(a==='invites'){showModal('Ваши приглашения',`<p class="modal-sub">Ссылки не хранятся открытым текстом. Потерянную ссылку нельзя восстановить — создайте новую.</p><div class="invitation-list">${current.invites.length?current.invites.map(i=>`<div class="invitation-item"><div><strong>${i.used_at?'Возражение получено':i.revoked_at?'Отозвано':i.expires_at<Date.now()?'Истекло':'Действует'}</strong><small>${date(i.created_at)}</small></div>${!i.revoked_at&&!i.used_at?B('Отозвать','revoke','small danger',`data-id="${i.id}"`):''}</div>`).join(''):'<p>Приглашений пока нет.</p>'}</div>`);return;}
 if(a==='revoke'){await command('revoke',{inviteId:button.dataset.id});closeModal();renderCase();toast('Приглашение отозвано.');return;}
 if(a==='handoff'){showModal('Передать бриф',`<p class="modal-sub">Сейчас семь сайтов не подключены. Для ненастроенных платформ будет подготовлен текст для ручного копирования — без заявления об успешной доставке.</p><form id="handoff-form"><div class="field"><label for="platform">Платформа</label><select id="platform" name="platformId">${boot.platforms.map(p=>`<option value="${p.id}">Платформа ${p.id} · ${p.configured?'настроенный контракт':'копирование'}</option>`).join('')}</select></div><label class="checkbox"><input type="checkbox" required name="consent"><span>Готов передать этот бриф выбранной платформе. Проверю её адрес перед переходом.</span></label><div class="inline-error" role="alert" hidden></div><button type="submit" class="btn primary full">Подготовить передачу</button></form>`);return;}
 if(a==='handoff-revoke')return showModal('Отозвать передачу?',`<p class="modal-sub">Подписанная ссылка станет недействительной, если платформа ещё не получила бриф. Если уже получила — отозвать данные из JUDGE нельзя.</p>${B('Отозвать ссылку','confirm-handoff-revoke','danger full',`data-id="${esc(button.dataset.id)}"`)}`);
 if(a==='confirm-handoff-revoke'){await command('handoff-revoke',{handoffId:button.dataset.id});closeModal();renderCase();toast('Передача отозвана.');return;}
 if(a==='copy-handoff')return copy(modal.querySelector('textarea').value);
 if(a==='ai'){showModal('Запросить внешний ИИ',`<p class="modal-sub">Будут отправлены: исходная и итоговая фразы, аудитория, факт, основание и ссылка на источник. Провайдер — OpenAI, модель ${esc(boot.ai.model)}. Возможны расходы API. ИИ не изменит решения дела.</p><form id="ai-form"><label class="checkbox"><input type="checkbox" required name="consent"><span>Разрешаю передать перечисленные данные провайдеру. Конфиденциальных сведений в них нет.</span></label><div class="inline-error" role="alert" hidden></div><button class="btn primary full" type="submit">Получить комментарии</button></form>`);return;}
 if(a==='sessions'){
  const data=await client.request('/auth/sessions');
  const rows=data.sessions.map(x=>`<div class="invitation-item"><div><strong>${esc(x.device)} ${x.current?'· этот сеанс':''}</strong><small>Создан: ${date(x.createdAt)} · посещение: ${x.lastSeenAt?date(x.lastSeenAt):'неизвестно'}</small></div>${B(x.current?'Выйти здесь':'Завершить','session-revoke','small danger',`data-id="${esc(x.id)}"`)}</div>`).join('');
  showModal('Активные сеансы',`<p class="modal-sub">Управляйте доступом с других устройств. После отзыва сеанс сразу перестаёт работать.</p><div class="invitation-list">${rows||'<p>Активных сеансов нет.</p>'}</div>`);return;
 }
 if(a==='session-revoke'){
  const r=await client.request('/auth/sessions/revoke',{method:'POST',body:{id:button.dataset.id}});
  closeModal();if(r.loggedOut){await render();toast('Вы вышли из текущего сеанса.');}else{await render();toast('Сеанс завершён.');}
  return;
 }
 if(a==='change-password'){
  showModal('Изменить пароль',`<p class="modal-sub">После изменения все другие сеансы будут завершены. Текущий сеанс получит новые ключи.</p><form id="password-form" class="modal-form">${field('currentPassword','Текущий пароль','',{required:true,type:'password',max:128})}${field('newPassword','Новый пароль','',{required:true,type:'password',max:128,help:'От 12 до 128 символов. Не используйте прежний пароль.'})}<div class="inline-error" role="alert" hidden></div><button type="submit" class="btn primary full">Изменить пароль и завершить другие сеансы</button></form>`);
  return;
 }
 if(a==='logout'){await client.request('/auth/logout',{method:'POST',body:{}});await render();toast('Вы вышли. Дела аккаунта сохранены.');return;}
 if(a==='export-data'){const data=await client.request('/privacy/export');download('JUDGE-personal-export.json',JSON.stringify(data,null,2),'application/json');toast('Экспорт подготовлен. Храните файл безопасно.');return;}
 if(a==='delete-data'){showModal('Удалить ваши данные?',`<p class="modal-sub">Дела, события, приглашения и аккаунт будут удалены из активной базы. Восстановления в интерфейсе нет. Введите DELETE для подтверждения.</p><form id="delete-form">${field('confirm','Подтверждение','',{required:true,max:10})}<div class="inline-error" role="alert" hidden></div><button class="btn danger full" type="submit">Удалить данные</button></form>`);return;}
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();if(busy&& !['close','menu'].includes(b.dataset.action))return;busy=true;b.disabled=true;try{await onAction(b);}catch(err){toast(err.message);if(err.code==='VERSION_CONFLICT'){await render();}}finally{busy=false;b.disabled=false;}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.id.endsWith('-form'))return;e.preventDefault();if(busy)return;if(!form.reportValidity())return;busy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;const d=Object.fromEntries(new FormData(form));
 try {
  if(await waves.submit(form,d))return;
  if(await governance.submit(form,d))return;
  if(await advanced.submit(form,d))return;
  if(await production.submit(form,d))return;
  if(await studio.submit(form,d))return;
  if(form.id==='new-form'){const r=await client.create({claim:d.claim,draft:{product:d.product,audience:d.audience}});navigate('/case/'+r.state.id);}
  if(form.id==='brief-form'){await command('brief',{draft:d});selectedVariant='';renderCase();}
  if(form.id==='verdict-form'){await command('verdict',{claim:d.claim,acknowledged:d.acknowledged==='on'});renderCase();toast('Бриф зафиксирован.');}
  if(form.id==='defend-form'){await command('defend',{text:d.text});renderCase();toast('Ответ сохранён в истории дела.');}
  if(form.id==='auth-form'){await client.request('/auth/'+form.dataset.mode,{method:'POST',body:{email:d.email,password:d.password,accepted:d.accepted==='on'}});closeModal();await render();toast('Вход выполнен. Ваши гостевые дела сохранены.');}
  if(form.id==='auth-recovery-request-form'){await client.request('/auth/recovery/request',{method:'POST',body:{email:d.email}});toast('Если аккаунт существует, письмо будет отправлено.');return;}
  if(form.id==='auth-recovery-confirm-form'){await client.request('/auth/recovery/confirm',{method:'POST',body:{code:d.code,newPassword:d.newPassword}});closeModal();toast('Пароль обновлён. Войдите заново.');return;}
  if(form.id==='settings-verify-form'){await client.request('/auth/verify/confirm',{method:'POST',body:{code:d.code}});closeModal();await render();toast('Адрес подтверждён.');return;}
  if(form.id==='password-form'){await client.request('/auth/password',{method:'POST',body:{currentPassword:d.currentPassword,newPassword:d.newPassword}});closeModal();await render();toast('Пароль изменён; другие устройства вышли.');}
  if(form.id==='comparison-start-form'){await command('comparison-start',{consent:d.consent==='on'});closeModal();renderCase();toast('Слепой тест создан. Теперь выдавайте индивидуальные ссылки.');}
  if(form.id==='compare-form'){await client.request('/compare/'+form.dataset.token,{method:'POST',body:{choice:d.choice,note:d.note||'',accepted:d.accepted==='on'}});shell(`<div class="empty card">${I('check')}<h2>Спасибо. Ваш выбор принят.</h2><p>Мы не показываем результаты до завершения опроса. Автор увидит ваш ответ в своём деле.</p><a href="#/new" class="btn primary">Проверить собственную фразу ${I('arrow')}</a></div>`,'Ответ принят','cases');}
  if(form.id==='invite-form'){const r=await command('invite',{consent:d.consent==='on'});const link=location.origin+location.pathname+'#/witness/'+r.invite.token;closeModal();renderCase();showModal('Приглашение готово',`<p class="modal-sub">Передайте ссылку другому человеку. Для локального теста откройте её в приватном окне. На другом компьютере ссылка localhost не сработает.</p><textarea class="link-box" readonly>${esc(link)}</textarea>${B(I('copy')+' Скопировать ссылку','copy-invite','primary full')}<p class="source-note">«Я защитил рекламную фразу в JUDGE. Найди слабое место, которое я пропустил — твоё возражение откроет дело повторно».</p>`);}
  if(form.id==='handoff-form'){const r=await command('handoff',{platformId:d.platformId,consent:d.consent==='on'});closeModal();renderCase();showModal('Бриф подготовлен',`<p class="modal-sub">${r.handoff.mode==='clipboard'?'Внешняя доставка не выполнена. Скопируйте бриф и вставьте в ваш рекламный инструмент.':'Адрес настроен оператором. Доставка ещё не подтверждена.'}</p><textarea class="link-box" readonly>${esc(r.handoff.text)}</textarea>${B(I('copy')+' Скопировать бриф','copy-handoff','primary full')}${r.handoff.url?`<a href="${esc(r.handoff.url)}" target="_blank" rel="noopener noreferrer" class="btn full top-gap">Открыть внешнюю платформу ${I('arrow')}</a>`:''}`);}
  if(form.id==='ai-form'){await command('ai',{consent:d.consent==='on'});closeModal();renderCase();toast('Комментарии ИИ сохранены отдельно от решений.');}
  if(form.id==='witness-form'){await client.request('/witness/'+form.dataset.token,{method:'POST',body:{text:d.text}});shell(`<div class="empty card">${I('check')}<h2>Ваше возражение изменило дело.</h2><p>Автор увидит его при следующем открытии или обновлении. Ссылка использована — второе возражение не создастся.</p><a href="#/new" class="btn primary">Проверить свою фразу ${I('arrow')}</a></div>`,'Свидетель','cases');}
  if(form.id==='delete-form'){await client.request('/privacy/delete',{method:'POST',body:{confirm:d.confirm}});closeModal();navigate('/');await render();toast('Данные удалены из активного хранилища.');}
 }catch(err){errorIn(form,err);if(err.code==='VERSION_CONFLICT')toast('Дело изменилось. Обновите страницу, сохранив ваш текст отдельно.');}finally{busy=false;submit.disabled=false;}
});
document.addEventListener('change',e=>{if(e.target.id==='judge-locale'){setLocale(e.target.value);render();}});
document.addEventListener('input',e=>{if(e.target.id==='case-search'){let matches=0;document.querySelectorAll('.case-list-row').forEach(row=>{row.hidden=!row.dataset.search.includes(e.target.value.toLowerCase());if(!row.hidden)matches++;});document.querySelector('#no-matches').hidden=matches>0;}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render();});
render();